ALTER TABLE media_objects DROP CONSTRAINT media_objects_purpose_check;
ALTER TABLE media_objects ADD CONSTRAINT media_objects_purpose_check CHECK(purpose IN('PORTFOLIO','SERVICE','PROJECT','CHAT'));
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL DEFAULT 'DIRECT' CHECK(kind IN('DIRECT','PROJECT')),project_id uuid REFERENCES projects(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((kind='PROJECT')=(project_id IS NOT NULL)));
CREATE UNIQUE INDEX conversations_project_unique ON conversations(project_id) WHERE project_id IS NOT NULL;
CREATE TABLE conversation_members(conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id),joined_at timestamptz NOT NULL DEFAULT now(),last_read_message_id uuid,muted_until timestamptz,archived_at timestamptz,PRIMARY KEY(conversation_id,user_id));
CREATE INDEX conversation_members_user_idx ON conversation_members(user_id,archived_at,joined_at DESC);
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_user_id uuid NOT NULL REFERENCES users(id),type text NOT NULL DEFAULT 'TEXT' CHECK(type IN('TEXT','IMAGE','FILE','SYSTEM')),body text CHECK(body IS NULL OR char_length(body)<=10000),reply_to_message_id uuid REFERENCES messages(id),client_message_id uuid,edited_at timestamptz,deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(body IS NOT NULL OR deleted_at IS NOT NULL OR type IN('IMAGE','FILE','SYSTEM')));
ALTER TABLE conversation_members ADD CONSTRAINT conversation_members_last_read_fk FOREIGN KEY(last_read_message_id) REFERENCES messages(id);
CREATE INDEX messages_conversation_created_idx ON messages(conversation_id,created_at DESC,id DESC);
CREATE INDEX messages_sender_created_idx ON messages(sender_user_id,created_at DESC);
CREATE UNIQUE INDEX messages_client_id_unique ON messages(sender_user_id,client_message_id) WHERE client_message_id IS NOT NULL;
CREATE TABLE message_media(message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,media_object_id uuid NOT NULL REFERENCES media_objects(id),PRIMARY KEY(message_id,media_object_id));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dedupe_key varchar(200) UNIQUE,user_id uuid NOT NULL REFERENCES users(id),type varchar(100) NOT NULL,actor_user_id uuid REFERENCES users(id),entity_type varchar(80),entity_id uuid,payload jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(payload)='object'),read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_user_unread_idx ON notifications(user_id,read_at,created_at DESC,id DESC);
CREATE INDEX notifications_user_created_idx ON notifications(user_id,created_at DESC,id DESC);
CREATE TABLE notification_preferences(user_id uuid NOT NULL REFERENCES users(id),event_type varchar(100) NOT NULL,in_app boolean NOT NULL DEFAULT true,email boolean NOT NULL DEFAULT true,telegram boolean NOT NULL DEFAULT false,push boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,event_type));
CREATE TABLE email_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dedupe_key varchar(200) NOT NULL UNIQUE,user_id uuid NOT NULL REFERENCES users(id),template varchar(100) NOT NULL,payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','SENDING','SENT','FAILED','DEAD')),attempts int NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 10),available_at timestamptz NOT NULL DEFAULT now(),last_error_code varchar(100),created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE INDEX email_jobs_pending_idx ON email_jobs(status,available_at) WHERE status IN('PENDING','FAILED');
